// Recursive Instantiation (The core mechanism of TMP)
template <int N>
struct Factorial {
    // Compiler action: Recursively instantiates template Factorial<N-1>
    // before determining its own value.
    static constexpr int value = N * Factorial<N - 1>::value;
};

// Full Specialization (Termination/Base Case)
// Halts the recursive instantiation process.
template <>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Usage: Forces the compiler to instantiate the chain Factorial<5>...Factorial<0>.
// Computation (120) happens entirely during compilation.
constexpr int Compile_Time_Result = Factorial<5>::value;

// Note: Recursive depth limit (default ~512) is a key constraint in TMP implementation.
